declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$allowed=['teacher','assistant_academic','head_academic','examination_officer','headteacher','sub_director','director'];if(!in_array($role,$allowed,true)){http_response_code(403);exit('Your role cannot access the question bank.');}$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$schoolId=(int)($_GET['school_id']??$schools[0]['id']);if(!in_array($schoolId,array_map('intval',array_column($schools,'id')),true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$schoolId)$schoolName=$s['name'];$csrf=csrf_token();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Question bank · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/api.js"></script><script defer src="assets/app.js"></script><script defer src="assets/question-bank.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Academics <span>/</span> Question bank</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content question-bank-page" data-api="api/question_bank.php" data-school="<?=$schoolId?>" data-user="<?=$uid?>" data-csrf="<?=e($csrf)?>" data-role="<?=e($role)?>"><section class="welcome-row"><div><div class="eyebrow">EXAMINATION ENGINE</div><h1>Question bank</h1><p class="muted"><?=e($schoolName)?> · Reviewed questions can be reused in examination papers.</p></div><?php if(count($schools)>1):?><form method="get"><label for="question-school">School</label><select id="question-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$schoolId?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><div id="question-status" class="notice" role="status" aria-live="polite" hidden></div><section class="note-create"><div class="section-heading"><div><div class="eyebrow">QUESTION AUTHORING</div><h2 id="question-form-title">Create a question</h2><p class="muted">New questions remain drafts until reviewed and published.</p></div></div><form id="question-form" class="note-form"><input type="hidden" name="action" value="save_qu