l for="question-guidance">Marking guidance</label><textarea id="question-guidance" name="marking_guidance" rows="3" maxlength="12000"></textarea></div><div class="question-wide"><label for="question-objectives">Learning objectives</label><textarea id="question-objectives" name="learning_objectives" rows="2" maxlength="6000"></textarea></div></div><div class="planning-actions"><button class="button primary" type="submit">Save draft</button><button class="button" type="button" id="question-reset">New question</button></div></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">REVIEW AND REUSE</div><h2>Questions</h2></div><button class="button" id="question-refresh" type="button">Refresh</button></div><div class="question-filters"><input id="question-search" type="search" placeholder="Search topic or question"><select id="question-status-filter"><option value="">All statuses</option><option value="draft">Draft</option><option value="submitted">Submitted</option><option value="approved">Approved</option><option value="returned">Returned</option><option value="published">Published</option><option value="archived">Archived</option></select></div><div id="question-list" class="question-list"><p class="muted">Loading questions…</p></div></section></div></main></div><dialog id="question-review-dialog" class="subject-dialog"><form method="dialog"><div class="subject-dialog-head"><div><div class="eyebrow">HUMAN REVIEW</div><h2>Review question</h2></div><button type="button" class="icon-button" data-close-question-review aria-label="Close">×</button></div><div class="subject-dialog-body"><input type="hidden" id="review-question-id"><p>Review the question and answer in the list, then choose a decision.</p><label for="question-review-feedback">Feedback <span class="muted">(required when returning)</span></label><textarea id="question-review-feedback" rows="4" maxlength="4000"></textarea><div class="planning-actions"><button type=